#!/usr/bin/env python3
"""Independent Pillow decoding of the files generated by Playwright browser smoke tests."""
from pathlib import Path
from PIL import Image, ImageChops
root = Path(__file__).resolve().parent / "artifacts"
for browser in ("chromium", "firefox"):
    with Image.open(root / f"{browser}.gif") as im:
        assert im.format == "GIF" and im.n_frames >= 3 and im.info.get("loop") == 0
        first = im.convert("RGB")
        changed = 0
        for i in range(1, im.n_frames):
            im.seek(i)
            current = im.convert("RGB")
            if ImageChops.difference(first, current).getbbox(): changed += 1
        assert changed >= 2, f"{browser}: static GIF instead of animated frames"
        print(f"{browser}: animated GIF {im.size}, {im.n_frames} frames ({changed} changed)")
    with Image.open(root / f"{browser}.png") as im:
        im.load()
        assert im.format == "PNG" and im.size == (1600, 900)
        print(f"{browser}: PNG valid {im.size}")
    blob=(root / f"{browser}.raymosaic").read_text(encoding="utf-8")
    import json
    project=json.loads(blob)
    assert project["format"]=="raymosaic" and project["version"]==1
    assert len(project["normals"])==448 and project["text"]=="LUNA"
    print(f"{browser}: project file roundtrip validated")
